  }

  const SCALES = { speed: ["--cfd-1 --cfd-2 --cfd-3 --cfd-4 --cfd-5", t("still air"), t("1.6 × road speed")], pressure: ["--cfd-2 --stage --cfd-5", t("suction"), t("pressing")] };
