    { readouts: [{ id: "top", label: t("Model top speed"), unit: t("km/h") }, { id: "quoted", label: t("Quoted"), unit: t("km/h") }] },
    { buttons: [{ id: "again", label: t("Run again"), onClick: () => { v = 0; hold = 0; } }] },
