// Shared test helpers: load the tour and every car config (pure data, no three.js).
import tour from "../../stops/tour.js";

export { tour };
export const loadCars = () => Promise.all(tour.map(async s => (await import(`../../stops/${s.slug}/car.js`)).default));

// The car.js fields a translation overlay (stops/<slug>/<lang>.js) must cover: page text and the labels subsystems show.
// Paths use "*" for any array index; legend entries are [token, text] pairs, so only their text is translated.
const TEXT = [
  "title", "name", "summary", "eyebrow", "lede", "note", "unverified.*", "photo.alt",
  "question", "look", "takeaway", "photo.caption",
  "components.*.label", "components.*.talk.*", "components.*.prompt", "components.*.answer", "components.*.more",
  "components.*.real.alt", "components.*.real.caption",
  ...["label", "engineLabel", "legendTitle", "links.*.name", "shapes.*.label", "types.*.label", "presets.*.label",
    "cases.*.label", "cases.*.say", "modes.*", "drive.gears.*.name", "legend.*.1", "surfaces.*.label",
    "consumers.*.label", "compare"].map(p => `components.*.params.${p}`),
];
const RULES = TEXT.map(p => new RegExp(`^${p.replace(/\./g, "\\.").replace(/\*/g, "[^.]+")}$`));
export const isText = path => RULES.some(r => r.test(path));

// Every string leaf of v as [path, value], path joined with ".".
export function leaves(v, path = []) {
  if (typeof v === "string") return [[path.join("."), v]];
  if (Array.isArray(v)) return v.flatMap((x, i) => leaves(x, [...path, i]));
  if (v && typeof v === "object") return Object.entries(v).flatMap(([k, x]) => leaves(x, [...path, k]));
  return [];
}

// The overlay shape for a car with only its text leaves; other array items become null (merge keeps the original).
export function skeleton(v, path = []) {
  if (typeof v === "string") return isText(path.join(".")) ? v : undefined;
  if (Array.isArray(v)) {
    const items = v.map((x, i) => skeleton(x, [...path, i]));
    return items.some(x => x !== undefined) ? items.map(x => x ?? null) : undefined;
  }
  if (v && typeof v === "object") {
    const out = {};
    for (const [k, x] of Object.entries(v)) { const s = skeleton(x, [...path, k]); if (s !== undefined) out[k] = s; }
    return Object.keys(out).length ? out : undefined;
  }
  return undefined;
}
// Translations: the UI catalog holds exactly the keys the code uses, with matching {n} placeholders; subsystem text goes
// through t(); every stop's stops/<slug>/hu.js covers exactly the text fields of its car.js.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { tour, loadCars, leaves, isText } from "./helpers.mjs";
import { merge } from "../../lib/app/i18n.js";
import hu from "../../lib/app/i18n/hu.js";

const root = new URL("../../", import.meta.url);
const read = p => readFileSync(new URL(p, root), "utf8");
const js = dir => readdirSync(new URL(dir, root)).filter(f => f.endsWith(".js")).map(f => [`${dir}${f}`, read(`${dir}${f}`)]);
const code = s => s.replace(/^\s*\/\/.*$/gm, "").replace(/\s\/\/ .*$/gm, "");   // comments may quote t("…")
const sources = [...js("lib/app/"), ...js("subsystems/")].filter(([f]) => f !== "lib/app/i18n.js").map(([f, s]) => [f, code(s)]);

const used = new Set();
for (const [, s] of sources) for (const m of s.matchAll(/\bt\(\s*"((?:[^"\\]|\\.)*)"/g)) used.add(JSON.parse(`"${m[1]}"`));
for (const f of readdirSync(root).filter(f => f.endsWith(".html"))) for (const m of read(f).matchAll(/data-i18n[^>]*>([^<]*)</g)) used.add(m[1].trim().replace(/\s+/g, " "));
for (const s of tour) used.add(s.room);   // shown with t(stop.room)

test("every text the code shows has a Hungarian translation", () => {
  assert.deepEqual([...used].filter(k => !(k in hu)), []);
  assert.deepEqual([...used].filter(k => k.includes("&")), [], "data-i18n text is read as textContent: write characters, not entities");
});

test("the Hungarian catalog has no unused keys", () => {
  assert.deepEqual(Object.keys(hu).filter(k => !used.has(k)), []);
});

test("translations keep their {n} placeholders", () => {
  const marks = s => [...s.matchAll(/\{\d\}/g)].map(m => m[0]).sort().join();
  assert.deepEqual(Object.entries(hu).filter(([k, v]) => marks(k) !== marks(v)).map(([k]) => k), []);
});

test("t() is called with a literal, so the tests can find every key", () => {
  const bad = [];
  for (const [f, s] of sources) for (const m of s.matchAll(/\bt\(\s*([^\s"])/g)) {
    const call = s.slice(m.index, m.index + 20);
    if (!/^t\((stop\.room|room\.name)\)/.test(call)) bad.push(`${f}: ${call}`);   // rooms: keys taken from stops/tour.js
  }
  assert.deepEqual(bad, []);
});

test("subsystem labels, units and legends go through t()", () => {
  const bad = [];
  for (const [f, s] of sources.filter(([f]) => f.startsWith("subsystems/"))) {
    for (const m of s.matchAll(/\b(?:label|unit|text|aria|top|bottom): "[^"]*[A-Za-z][^"]*"|toggle: \["|\["--[a-z0-9-]+", "[^"]*[A-Za-z]/g)) bad.push(`${f}: ${m[0]}`);
  }
  assert.deepEqual(bad, []);
});

const cars = await loadCars();
for (const [i, s] of tour.entries()) {
  test(`${s.slug}: hu.js translates every text field of car.js and nothing else`, async () => {
    const car = cars[i], over = (await import(`../../stops/${s.slug}/hu.js`)).default;
    const text = new Map(leaves(car).filter(([p]) => isText(p))), got = new Map(leaves(over));
    assert.deepEqual([...text.keys()].filter(p => !got.get(p)?.trim()), [], "untranslated");
    assert.deepEqual([...got.keys()].filter(p => !text.has(p)), [], "not a text field of car.js");
    assert.deepEqual(leaves(merge(car, over)).filter(([p]) => !isText(p)), leaves(car).filter(([p]) => !isText(p)));
    // Hungarian writes a decimal comma; model names such as "300 SEL 6.3" or "190 E 2.5-16" keep their point.
    assert.deepEqual([...got.values()].filter(v => /\d\.\d/.test(v.replace(/SEL 6\.3|SLC 5\.0|\b2\.[35]-16/g, ""))), [], "decimal point");
  });
}

// Declarative side-panel cards. A subsystem describes its cards; this builds the DOM (textContent only) and returns handles.
// Card: { label, badge?: { id, text }, only?: "model" | "photo", detail?, items: [widget] }. Widgets (one key each, plus
// optional `only` and `detail`):
//   readouts: [{ id, label, unit, value }]          → ui.set(id, text)
//   trace: { id, series: [{ token, min, max }], span, top, bottom, aria }   → ui.trace(id).push(t, [v…]) / .draw(t)
//   buttons: [{ id, label, toggle?: [onLabel, offLabel], pressed?, onClick(pressed) }]   → ui.toggle(id).set(bool)
//   slider: { id, label, min, max, step, value, onInput(v) }   → ui.slider(id).set(v)
//   meter: { id }  → ui.meter(id).set(0..1, hot)        cells: { id, labels }  → ui.cells(id).set(i, text, on) / .label(i, text)
//   legend: [[token, name]]   key: [[token, text]]   svg: { id, viewBox, aria }  → ui.el(id)   text: "…" | { id, value } → ui.set(id, text)   list: ["…"]
// Text arrives already translated (subsystems use ctx.t); readout values are written with the local decimal mark.
// ui.state() lists the settings the visitor chose (toggles, radio buttons, sliders; in the order last used) and
// ui.restore(state) replays them through the same handlers, so a reloaded page (the language switch) shows the same
// experiment. Buttons with neither toggle nor pressed are momentary and not kept.
// Element ids are `${scope}-${id}`: scope defaults to the component id; pages with several cars pass one per car.
// Depth: a widget or card marked `detail` (readings, legends, secondary controls) goes to detailContainer, the story's named
// disclosure under the mechanism's key experiment; the rest of its card stays in container. Without a separate
// detailContainer every card stays whole, in order. A split card keeps its label (and badge) on the part in container;
// its part in detailContainer repeats the label's text.
import { num } from "./i18n.js";
import { h } from "./dom.js";

export function createPanel(container, compId, scope = compId, detailContainer = container) {
  const els = new Map(), api = {};
  const controls = new Map(), used = new Set();   // id → { get(), apply(value) }; ids the visitor set, last used last
  const use = id => { used.delete(id); used.add(id); };
  const key = id => `${scope}-${id}`;

  const widgets = {
    readouts: items => h("div", { class: "readouts" }, items.map(r => {
      const o = h("output", { id: key(r.id) }, r.value == null ? "–" : num(r.value)); els.set(r.id, o);
      return h("div", {}, h("small", {}, r.label), o, h("small", {}, r.unit ?? ""));
    })),
    trace: t => {
      const svg = h("svg:svg", { viewBox: "0 0 280 110", role: "img", "aria-label": t.aria ?? "" });
      const grid = [[55, null], [5, "2 3"], [105, "2 3"]].map(([y, dash]) => h("svg:line", { x1: 0, y1: y, x2: 280, y2: y, stroke: "var(--rule)", "stroke-dasharray": dash }));
      const lines = t.series.map(s => h("svg:polyline", { fill: "none", stroke: `var(${s.token})`, "stroke-width": 1.6 }));
      svg.append(...grid, ...lines, h("svg:text", { x: 278, y: 15, "text-anchor": "end" }, t.top ?? ""), h("svg:text", { x: 278, y: 101, "text-anchor": "end" }, t.bottom ?? ""));
      const buf = [], span = t.span ?? 6;
      els.set(t.id, {
        push(time, values) { buf.push({ time, values }); },
        draw(now) {
          while (buf.length && buf[0].time < now - span) buf.shift();
          const X = tt => ((tt - (now - span)) / span * 280).toFixed(1);
          t.series.forEach((s, i) => lines[i].setAttribute("points", buf.map(p => {
            const v = Math.max(s.min, Math.min(s.max, p.values[i]));
            return `${X(p.time)},${(105 - (v - s.min) / (s.max - s.min) * 100).toFixed(1)}`;
          }).join(" ")));
        },
      });
      return h("div", { class: "trace" }, svg);
    },
    buttons: items => h("div", { class: "row" }, items.map(b => {
      // toggle: [onLabel, offLabel] flips itself; pressed without toggle = radio-style button whose state the caller sets.
      const el = h("button", { type: "button", "aria-pressed": b.toggle || b.pressed != null ? String(!!b.pressed) : null }, b.toggle ? b.toggle[b.pressed ? 0 : 1] : b.label);
      const handle = { el, pressed: !!b.pressed, set(p) { handle.pressed = p; el.setAttribute("aria-pressed", String(p)); if (b.toggle) el.textContent = b.toggle[p ? 0 : 1]; } };
      const kept = b.toggle || b.pressed != null;
      el.addEventListener("click", () => { if (b.toggle) handle.set(!handle.pressed); if (kept) use(b.id); b.onClick?.(handle.pressed); });
      // A radio-style button is replayed only if it was the pressed one; a toggle only if it differs.
      if (kept) controls.set(b.id, { get: () => handle.pressed, apply: v => { if (b.toggle ? v !== handle.pressed : v) el.click(); } });
      els.set(b.id, handle);
      return el;
    })),
    slider: s => {
      const input = h("input", { id: key(s.id), type: "range", min: s.min, max: s.max, step: s.step ?? 1, value: s.value });
      const changed = () => { use(s.id); s.onInput?.(+input.value); };
      input.addEventListener("input", changed);
      controls.set(s.id, { get: () => +input.value, apply: v => { input.value = v; changed(); } });
      els.set(s.id, { el: input, set(v) { input.value = v; } });
      return h("div", { class: "slider" }, h("label", { class: "label", for: key(s.id) }, s.label), input);
    },
    meter: m => { const bar = h("i"), el = h("div", { class: "meter" }, bar); els.set(m.id, { set(f, hot) { bar.style.width = `${(Math.max(0, Math.min(1, f)) * 100).toFixed(0)}%`; el.classList.toggle("hot", !!hot); } }); return el; },
    cells: c => {
      const cells = c.labels.map(l => h("div", { class: "cyl" }, h("b", {}, l), h("span", {}, "–")));
      // Up to four in a row; half as many where a word in a cell would not fit (a long label on a phone), checked again
      // whenever the row's width or a label changes.
      const n = Math.min(c.labels.length, 4), row = h("div", { class: "cyls", style: `--n:${n}` }, cells);
      const fit = () => {
        row.style.setProperty("--n", n);
        if (n > 2 && cells.some(el => el.scrollWidth > el.clientWidth)) row.style.setProperty("--n", Math.ceil(n / 2));
      };
      let width = -1;   // refit on a change of width only, a frame later: refitting changes the row's height
      new ResizeObserver(([e]) => { if (e.contentRect.width !== width) { width = e.contentRect.width; requestAnimationFrame(fit); } }).observe(row);
      els.set(c.id, {
        set(i, text, on) { const el = cells[i]; if (el.dataset.s !== text) { el.dataset.s = text; el.lastChild.textContent = text; } el.classList.toggle("power", !!on); },
        label(i, text) { const b = cells[i].firstChild; if (b.textContent !== text) { b.textContent = text; fit(); } },
      });
      return row;
    },
    legend: items => h("ul", { class: "legend" }, items.map(([tok, name]) => h("li", {}, h("span", { class: "sw", style: `background:var(${tok})` }), name))),
    key: items => h("div", { class: "key" }, items.map(([tok, text]) => h("span", {}, h("i", { style: `background:var(${tok})` }), text))),
    svg: s => { const el = h("svg:svg", { viewBox: s.viewBox, role: "img", "aria-label": s.aria ?? "", class: "diagram" }); els.set(s.id, el); return el; },
    text: t => {   // "…", or { id, value } for a sentence the subsystem rewrites (ui.set(id, text); read out when it changes)
      if (typeof t === "string") return h("p", { class: "note" }, t);
      const el = h("p", { class: "note", "aria-live": "polite" }, t.value ?? ""); els.set(t.id, { set value(v) { el.textContent = v; } }); return el;
    },
    list: items => h("ul", { class: "talk" }, items.map(t => h("li", {}, t))),
  };

  // Append cards; returns the shared handle API (call again to add more cards for the same component).
  return function cards(list) {
    const split = detailContainer !== container;
    for (const card of list) {
      const label = h("div", { class: "label" }, card.label ?? "");
      if (card.badge) { const b = h("span", { class: "badge" }, card.badge.text); label.append(" · ", b); els.set(card.badge.id, { set(text, on) { b.textContent = text; b.classList.toggle("on", !!on); } }); }
      const items = card.items ?? [], deep = w => split && (card.detail || w.detail);
      const main = items.filter(w => !deep(w)), more = items.filter(deep);
      const box = (lab, ws, into) => {
        if (!ws.length && !lab) return;
        const el = h("div", { class: "panel", "data-comp": compId, "data-only": card.only }, lab);
        for (const w of ws) {
          const [type] = Object.keys(w).filter(k => k !== "only" && k !== "detail");
          const node = widgets[type](w[type]);
          if (w.only) node.dataset.only = w.only;
          el.append(node);
        }
        into.append(el);
      };
      const head = main.length > 0 || !more.length;   // the label goes where the card's experiment is
      box(head ? label : null, main, container);
      box(head ? (more.length && card.label ? h("div", { class: "label" }, card.label) : null) : label, more, detailContainer);
    }
    return Object.assign(api, {
      set: (id, text) => { els.get(id).value = num(text); },
      el: id => els.get(id), trace: id => els.get(id), toggle: id => els.get(id), slider: id => els.get(id),
      meter: id => els.get(id), cells: id => els.get(id), badge: id => els.get(id),
      state: () => [...used].map(id => [id, controls.get(id).get()]),
      restore: state => { for (const [id, v] of state ?? []) controls.get(id)?.apply(v); },
    });
  };
}

// After one visit with signal every stop works with no network (Chromium: Playwright's SW support is reliable there).
import { test, expect } from "@playwright/test";
import tour from "../../stops/tour.js";

test("one visit stores the whole tour; another stop then opens offline", async ({ page, context }) => {
  await page.goto("./?sw=1");   // service worker is skipped on localhost unless asked for
  await expect(page.locator("#status")).toContainText("Ready offline", { timeout: 30_000 });
  await context.setOffline(true);
  const slug = tour.at(-1).slug;
  await page.goto(`stop.html?s=${slug}&sw=1&debug`);
  await page.waitForFunction(() => window.__tour?.stories[0].frames() > 5, null, { timeout: 20_000 });
  await page.goto("./?sw=1");
  await expect(page.locator('a[href^="stop.html?s="]')).toHaveCount(tour.length);
  await page.goto("teaser.html?sw=1");
  await expect(page.locator('a[href^="stop.html?s="]')).toHaveCount(3);
});
// Every stop on the route loads, renders and animates, and scrolling its story sets what the stage shows, on each emulated
// device.
import { test, expect } from "@playwright/test";
import tour, { teaser } from "../../stops/tour.js";
import { watchErrors, stepsOf, shown } from "./helpers.mjs";

const cars = await Promise.all(tour.map(async s => (await import(`../../stops/${s.slug}/car.js`)).default));

for (const car of cars) {
  test(`${car.slug}: the story's steps set the stage, readouts move`, async ({ page }) => {
    const errors = watchErrors(page);
    await page.goto(`stop.html?s=${car.slug}&debug`);
    await page.waitForFunction(() => window.__tour?.stories[0].frames() > 10, null, { timeout: 20_000 });
    await expect(page.locator(".step")).toHaveCount(car.components.length + 2);

    const pinned = new Set();
    for (const [k, want] of stepsOf(car).entries()) {
      const step = page.locator(".step").nth(k);
      await step.evaluate(s => s.scrollIntoView({ block: "center" }));
      await expect.poll(() => shown(page)).toEqual({ step: k, state: want });
      await expect(page.locator(".stage img")).toBeVisible({ visible: want.view === "photo" });
      if (k === 0 || k > car.components.length) continue;   // intro and background: no component cards
      pinned.add(await page.locator(".stage").evaluate(s => Math.round(s.getBoundingClientRect().top)));
      await expect.poll(() => page.evaluate(() => window.__tour.stories[0].triangles())).toBeGreaterThan(0);
      const readouts = () => step.locator(`.panel[data-comp="${want.comp}"] output`).allTextContents();
      const before = await readouts();
      expect(before.length).toBeGreaterThan(0);
      // Precomputed results (race-aero) stand still until another case is chosen: press the first case button (race-aero starts
      // on a later one; animated components move either way).
      if (car.components.find(c => c.id === want.comp).params.cases) await step.locator(`.panel[data-comp="${want.comp}"] button`).first().click();
      await expect.poll(readouts, { timeout: 15_000 }).not.toEqual(before);
    }
    expect(pinned.size, "stage stays put through the component steps").toBe(1);

    const fit = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, w: innerWidth, h: innerHeight, stage: document.querySelector(".stage").getBoundingClientRect().height }));
    expect(fit.scrollW, "no horizontal scroll").toBeLessThanOrEqual(fit.w);
    expect(fit.stage, "stage fits the viewport height").toBeLessThanOrEqual(fit.h);
    expect(errors).toEqual([]);
  });
}

