const LOW = 250;   // below this height the front of the body is the lip (mm)

export function voxelize({ parts }, { h, x0, nx, ny, nz }, mode = "base") {
  const N = nx * ny * nz, solid = new Uint8Array(N), at = (i, j, k) => (k * ny + j) * nx + i;
